function makeWakeUserHandler(wakeOnce, getUser) {
  return async ({ event, step }) => {
    const uid = event.data && event.data.uid;
    if (!uid) return;
    const u = await step.run("fetch", () => (getUser || getUserByUid)(uid));
    if (!u) return;
    await step.run("wake", () => wakeOnce(u, Date.now()));
  };
}
